  'Code from your other device': 'Код с другого устройства',
  'Confirm with a passkey': 'Подтвердить ключом доступа',
  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': 'Подтверждено. Теперь создайте новый ключ доступа; браузер спросит, где его хранить.',
  'Copy link': 'Копировать ссылку',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': 'Создайте на этом устройстве ключ доступа для профиля «{0}». Теперь здесь вы будете входить с ним.',
  'Enter the code from your other device.': 'Введите код с другого устройства.',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'Для этого устройства, аппаратного ключа, менеджера паролей или телефона через QR-код самого браузера. Сначала подтвердите, что это вы.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'С ним больше нельзя будет войти в этот профиль. Устройство, которое уже вошло с ним, останется в аккаунте. Если оно потеряно, используйте «Выйти на всех устройствах».',
  'It is your only way in, so it cannot be removed until there is another.': 'Это ваш единственный способ войти, поэтому его нельзя удалить, пока нет другого.',
  'Last used {0}': 'Последнее использование: {0}',
  'Make a new code': 'Создать новый код',
  'Name, e.g. Work laptop': 'Название, например Рабочий ноутбук',
  'None yet. Add one and sign in without your password.': 'Пока нет. Добавьте ключ и входите без пароля.',
  'Passkey added': 'Ключ доступа добавлен',
  'Passkey removed': 'Ключ доступа удалён',
  'Passkey {0}': 'Ключ доступа {0}',
  'Passkeys': 'Ключи доступа',
  'Remove passkey': 'Удалить ключ доступа',
  'Remove this passkey?': 'Удалить этот ключ доступа?',
  'Scan this with the other device, or open Gains there and enter the code on the sign-in screen. It works once, for {0} minutes.': 'Отсканируйте это другим устройством или откройте там Gains и введите код на экране входа. Код работает один раз в течение {0} минут.',
  'This browser cannot confirm with your passkey. Do this on a device that holds one.': 'Этот браузер не может подтвердить вашим ключом доступа. Сделайте это на устройстве, где он хранится.',
  'First confirm that it is you.': 'Сначала подтвердите, что это вы.',
  'This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.': 'У этого профиля нет ключа доступа, а этот сервер не принимает пароли, поэтому здесь нечем подтвердить, что это вы. Обратитесь к администратору.',
  'This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.': 'Этот браузер не умеет создавать ключи доступа, поэтому его нельзя добавить по коду. Откройте ссылку в браузере, который это умеет.',
  'This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.': 'В этом браузере выполнен вход как «{0}». Если добавить его к «{1}», «{0}» здесь выйдет из аккаунта.',
  'This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.': 'Этот код от другого профиля, который тоже называется «{0}», а не от того, под которым выполнен вход в этом браузере. Если добавить браузер туда, ваш профиль здесь выйдет из системы.',
  'Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.': 'Продолжайте, только если этот код пришёл с вашего собственного устройства. Тогда в этом браузере будет выполнен вход в «{0}», и всё, что вы здесь запишете, попадёт в этот профиль.',
  'This code has expired.': 'Срок действия кода истёк.',
  'This device already has a passkey for this profile.': 'На этом устройстве уже есть ключ доступа для этого профиля.',
  'This passkey already belongs to a profile.': 'Этот ключ доступа уже принадлежит профилю.',
  'This profile already has as many passkeys as it can hold.': 'У этого профиля уже максимальное число ключей доступа.',
  'Use a code from your other device': 'Использовать код с другого устройства',
  'You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.': 'Вы получите код, с которым ваш телефон или другой компьютер сможет создать ключ доступа для этого профиля. Сначала подтвердите, что это вы.',
