  'Sign out everywhere?': 'Выйти на всех устройствах?',
  'You have a workout running. It waits on this device until you’re back on this account.': 'У вас идёт тренировка. Она подождёт на этом устройстве, пока вы не вернётесь в этот аккаунт.',
  'Sign out everywhere': 'Выйти на всех устройствах',
