  'The Coach is on': 'Тренер включён',
  'Before the Coach starts': 'Прежде чем Тренер начнёт',
  'When you ask for a plan or a review, this instance sends the following to {0}, running on this server under the instance owner’s account.': 'Когда вы запрашиваете план или разбор, этот сервер отправляет следующее в {0}, работающий здесь под учётной записью владельца.',
  'the configured AI provider': 'настроенного поставщика ИИ',
  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': 'Ваше имя, данные для входа и всё остальное из вашей учётной записи остаются здесь. Данные других людей никогда не передаются.',
  'You can turn this off at any time, which also discards anything the Coach is holding for you.': 'Вы можете отключить это в любой момент. Тогда всё, что Тренер держит для вас, тоже удалится.',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'Тренер не врач и не физиотерапевт. Если что-то болит, обратитесь к специалисту.',
  'Not now': 'Не сейчас',
  'Meet the Coach': 'Познакомьтесь с Тренером',
  'An AI coach that can design your plan and adjust it from what you actually log. It runs on this server, it never changes anything without your say-so, and it is off until you turn it on.': 'ИИ-тренер, который составляет ваш план и корректирует его по тому, что вы записываете. Он работает на этом сервере, никогда ничего не меняет без вашего согласия и выключен, пока вы его не включите.',
  'See what it would use': 'Посмотреть, какие данные он возьмёт',
  'The Coach is thinking…': 'Тренер думает…',
  'Your plan is ready': 'Ваш план готов',
  'Suggestions ready': 'Предложения готовы',
  '{0} routines to look over': '{0} программ для просмотра',
  'Review': 'Посмотреть',
  'Automatic reviews': 'Автоматические разборы',
  'Off. The Coach only looks when you ask.': 'Выключено. Тренер смотрит, только когда вы просите.',
  'You are only notified when the Coach actually has something to suggest.': 'Уведомление приходит, только если Тренеру действительно есть что предложить.',
  'When': 'Когда',
  'Weekly': 'Еженедельно',
  'On a day and time you choose': 'В выбранный день и час',
  'After every few workouts': 'Каждые несколько тренировок',
  'As soon as you have logged enough': 'Как только наберётся достаточно записей',
  'Day': 'День',
  'After how many workouts': 'Через сколько тренировок',
  'Plan from the Coach': 'План от Тренера',
  'Coach review': 'Разбор Тренера',
  'Based on {0} sessions': 'По данным {0} занятий',
