  'Built a plan': 'Составил план',
  'Undid the last changes': 'Отменил последние изменения',
  'Reviewed your training': 'Разобрал ваши тренировки',
  '{0} applied': 'применено: {0}',
  'The Coach is building your plan…': 'Тренер составляет ваш план…',
  'Your plan': 'Ваш план',
  'Step {0} of {1}': 'Шаг {0} из {1}',
  'What are you training for?': 'Ради чего вы тренируетесь?',
  'Where are you starting from?': 'С чего вы начинаете?',
  'How many days a week?': 'Сколько дней в неделю?',
  'Which days suit you? (optional)': 'Какие дни вам удобны? (необязательно)',
  'How long is a session?': 'Сколько длится занятие?',
  'min': 'мин',
  'The Coach fits the volume to the time you actually have, including rest between sets.': 'Тренер подгоняет объём под то время, которое у вас есть, включая отдых между подходами.',
  'What can you train with?': 'С каким оборудованием вы тренируетесь?',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'Отметьте всё, к чему у вас есть доступ. Если оставить пустым, Тренер использует всю библиотеку.',
  'Anything to work around?': 'Что-то нужно обойти?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'Травмы, ноющие суставы, недоступные движения или бытовые ограничения, например тренировка в 6 утра в квартире.',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'напр. «капризное левое плечо, без жима штанги над головой»',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'Если что-то действительно болит, обратитесь к специалисту. Тренер будет составлять план осторожно, но ставить диагнозы он не умеет.',
  'Anything else?': 'Что-нибудь ещё?',
  'Exercises you love': 'Упражнения, которые вам нравятся',
  'e.g. “deadlifts, anything with a kettlebell”': 'напр. «становая тяга, всё с гирей»',
  'Exercises you would rather not': 'Упражнения, которых вы предпочли бы избежать',
  'e.g. “I hate lunges”': 'напр. «ненавижу выпады»',
  'Anything you want the Coach to know': 'Что ещё стоит знать Тренеру',
  'e.g. “I want visible arms progress by spring”': 'напр. «хочу заметный прогресс по рукам к весне»',
  'Build my plan': 'Составить мой план',
  'Pick a goal and where you are starting from to continue.': 'Выберите цель и отправную точку, чтобы продолжить.',
  'Your plan is live': 'Ваш план активен',
  'That proposal can’t be read.': 'Это предложение не читается.',
  'The Coach is revising it…': 'Тренер вносит правки…',
  'Revision {0}': 'Версия {0}',
  'Replaces your current week. Days this plan leaves empty become rest days.': 'Заменит вашу текущую неделю. Дни, которые план оставляет пустыми, станут днями отдыха.',
  'Want something different?': 'Хотите иначе?',
  'Say it in your own words and the Coach will revise the whole plan.': 'Скажите своими словами, и Тренер переработает весь план.',
  'Ask for a revision': 'Запросить правку',
  'Accept plan': 'Принять план',
  'Could not apply those changes': 'Не удалось применить эти изменения',
  'Dismiss': 'Отклонить',
  'Coach suggestions': 'Предложения Тренера',
  'Based on your last {0} sessions': 'По вашим последним {0} занятиям',
  'Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.': 'Ваш план изменился с тех пор, как Тренер его смотрел. Предложения, которые больше не подходят, показаны серым. Запросите новый разбор, чтобы увидеть их снова.',
  'Doesn’t match your plan any more, so it can’t be applied.': 'Больше не соответствует вашему плану, поэтому применить нельзя.',
  'Notes from the Coach': 'Заметки Тренера',
  'These change nothing on their own.': 'Сами по себе они ничего не меняют.',
  'Reverted the last Coach changes.': 'Последние изменения Тренера отменены.',
  'Before the Coach’s plan': 'До плана Тренера',
  'Before the Coach’s changes': 'До изменений Тренера',
