  'Disconnected. Back to local-only': 'Отключено. Снова только локально',
  'Connect to my server': 'Подключиться к моему серверу',
  'Sync this device to your own self-hosted Gains instead.': 'Синхронизировать это устройство с вашим собственным self-hosted Gains.',
  'Pair the mobile app': 'Сопряжение мобильного приложения',
  'Connect the Gains app on your phone to this account.': 'Подключите приложение Gains на телефоне к этому аккаунту.',
  'Could not generate a code': 'Не удалось создать код',
  'On the Gains app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.': 'В приложении Gains выберите «Подключиться к моему серверу», затем введите этот адрес и код ниже. Он действителен 5 минут.',
