  'Your server can’t be reached. Your changes are saved on this device and sync once it answers again.': 'Ваш сервер недоступен. Изменения сохранены на этом устройстве и синхронизируются, как только он снова ответит.',
  'Your server can’t be reached. Showing the last copy synced with it.': 'Ваш сервер недоступен. Показана последняя копия, синхронизированная с ним.',
  'Server address unknown': 'Адрес сервера неизвестен',
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Выполните сопряжение заново или сначала экспортируйте резервную копию. Если всё равно продолжить, копия этих изменений останется на этом устройстве, пока оно снова не подключится к этому серверу с этим аккаунтом. Тогда они будут добавлены обратно.',
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Войдите снова или сначала экспортируйте резервную копию. Если всё равно продолжить, копия этих изменений останется на этом устройстве, пока оно снова не подключится к этому серверу с этим аккаунтом. Тогда они будут добавлены обратно.',
