  'This folder can’t be used for backups.': 'Эту папку нельзя использовать для резервных копий.',
  'Gains can no longer write to “{0}”, so copies go to Documents/Gains again. Choose the folder again to switch back.': 'Gains больше не может записывать в «{0}», поэтому копии снова сохраняются в Documents/Gains. Выберите папку заново, чтобы вернуться к ней.',
  'Gains can no longer write to the chosen folder, so copies go to Documents/Gains again. Choose the folder again to switch back.': 'Gains больше не может записывать в выбранную папку, поэтому копии снова сохраняются в Documents/Gains. Выберите папку заново, чтобы вернуться к ней.',
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': 'Напоминать, если я пропускаю запланированную тренировку',
  'Nudge tone': 'Тон напоминания',
  'Friendly': 'Дружелюбный',
  'Guilt trip': 'Давить на совесть',
  'Drill sergeant': 'Сержант-инструктор',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'Одно напоминание вечером запланированного дня без записанной тренировки, с 20:00 до 21:30. После 3 пропущенных дней подряд оно замолкает до вашей следующей тренировки.',
  'Everything okay?': 'Всё в порядке?',
  '{0} is still waiting. What’s up?': 'Тренировка «{0}» всё ещё ждёт. Что случилось?',
  'No {0} today? Even a short session tomorrow counts.': 'Сегодня без тренировки «{0}»? Завтра засчитается даже короткая.',
  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'Тяжёлый день? Тренировка «{0}» подождёт. Завтра будет новый старт.',
  'Hey, {0} didn’t happen today. All good?': 'Эй, тренировка «{0}» сегодня не состоялась. Всё хорошо?',
  'I miss you': 'Я скучаю по вам',
  '{0} waited by the door all evening. For you.': 'Тренировка «{0}» весь вечер ждала вас у двери. Именно вас.',
  'The barbell asked about you today. I didn’t know what to say.': 'Штанга сегодня спрашивала о вас. Я не знал, что ответить.',
  'Was it something I said? {0} misses you.': 'Я что-то не то сказал? Тренировка «{0}» скучает по вам.',
  'I saved you a spot on the bench. It’s still empty.': 'Я занял вам место на скамье. Оно всё ещё пустое.',
  'Attention, recruit!': 'Смирно, новобранец!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'Ваши достижения пакуют чемоданы. Завтра «{0}», без отговорок!',
  '{0} doesn’t do itself, recruit. Move it!': 'Тренировка «{0}» сама себя не сделает, новобранец. Шевелитесь!',
  'Excuses don’t lift weights. Report for {0} tomorrow!': 'Отговорки не поднимают веса. Завтра явиться на «{0}»!',
  'Your muscles filed a missing-person report. Show up for {0}!': 'Ваши мышцы подали заявление о пропаже. Явиться на «{0}»!',
  'That address answers, but it isn’t a Gains server. Check the URL.': 'По этому адресу что-то отвечает, но это не сервер Gains. Проверьте URL.',
  'That address answers, but a login page or proxy rule replied instead of Gains. Let /api/ through to Gains unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': 'По этому адресу отвечает страница входа или правило прокси, а не Gains. Пропустите /api/ до Gains без изменений. См. “Phone app and CORS” в docs/SELF_HOSTING.md.',
  'Switch sides': 'Смените сторону',
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': 'Сохраняет копию с датой в «{0}» после каждой тренировки или правки программы и хранит {1} последних.',
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': 'Сохраняет копию с датой в выбранную папку после каждой тренировки или правки программы и хранит {0} последних.',
