  'The same routines on the same weekdays, every week.': 'Одни и те же программы в одни и те же дни, каждую неделю.',
  'How you train': 'Как вы тренируетесь',
  '{0} of {1} done this round.': '{0} из {1} сделано в этом круге.',
  'Drag to reorder. Tap the minus to take one out.': 'Перетащите, чтобы изменить порядок. Нажмите минус, чтобы убрать одну.',
  'Start the loop over': 'Начать круг заново',
