  'Finished workouts and weigh-ins, from this phone only.': 'Завершённые тренировки и взвешивания, только с этого телефона.',
  'Open Health Connect': 'Открыть Health Connect',
  'Install Health Connect to share workouts and weigh-ins with other apps.': 'Установите Health Connect, чтобы делиться тренировками и взвешиваниями с другими приложениями.',
  'Update Health Connect to share workouts and weigh-ins with other apps.': 'Обновите Health Connect, чтобы делиться тренировками и взвешиваниями с другими приложениями.',
  'Permission withdrawn. Tap to allow again': 'Разрешение отозвано — нажмите, чтобы выдать снова',
  'Workouts and weigh-ins go to Health Connect when you finish or change them. Gains reads nothing back.': 'Тренировки и взвешивания попадают в Health Connect, когда вы их завершаете или меняете. Gains ничего оттуда не читает.',
  'Health Connect permission not granted': 'Разрешение Health Connect не выдано',
  'Could not write to Health Connect': 'Не удалось записать в Health Connect',
  'Writing to Health Connect': 'Запись в Health Connect включена',
  'Stop writing to Health Connect?': 'Перестать записывать в Health Connect?',
  'What Gains already wrote can stay in Health Connect as your data, or be removed from it.': 'То, что Gains уже записал, может остаться в Health Connect как ваши данные или быть оттуда удалено.',
  'Stop, keep what it wrote': 'Остановить, оставить записанное',
  'Stop and remove what it wrote': 'Остановить и удалить записанное',
  'Could not remove it from Health Connect': 'Не удалось удалить из Health Connect',
  'e.g. “swap the squats for split squats, and Mondays are short”': 'например: «замени приседания на выпады, а по понедельникам короче»',
  'Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, and you can still change any of them mid-session.': 'Добавляются перед рабочими подходами и не учитываются в объёме, рекордах и прогрессии. Каждый закрывает половину разницы до рабочего веса, и любой можно поменять прямо во время тренировки.',
  'The app can only pair with an https:// address. Your phone blocks plain http:// before anything is even sent.': 'Приложение умеет подключаться только к адресу https://. Телефон блокирует обычный http:// ещё до отправки.',
  '1RM formula': 'Формула 1ПМ',
  'A blend of seven formulas: calculated from one set, not a tested max.': 'Смесь семи формул: считается по одному подходу, это не проверенный максимум.',
  'Averages seven formulas and reads your RIR when you log it.': 'Усредняет семь формул и учитывает ваш RIR, если вы его записали.',
